<template>
  <div id="app">
    <!-- 背景容器 -->
    <div class="box-xk">
      <!-- 黄瓜背景图片 -->
      <div class="background-image"></div>
      
      <!-- 星空效果（可选，如需保留可取消注释） -->
      <!-- <div id="stars"></div>
      <div id="stars2"></div>
      <div id="stars3"></div> -->
      
      <!-- 原有内容 -->
      <Navbar />
      <router-view />
    </div>
  </div>
</template>

<script>
import { onMounted, onUnmounted } from 'vue';
import Navbar from './components/Navbar.vue';

// 星空创建函数（如果保留星空效果可使用）
function createStars() {
  const starsContainers = ['stars', 'stars2', 'stars3'];
  const totalStars = 300;
  
  starsContainers.forEach((id, index) => {
    const container = document.getElementById(id);
    if (!container) return;
    
    // 清空容器，避免重复创建
    container.innerHTML = '';
    
    const starsCount = Math.floor(totalStars / starsContainers.length) + 
                       (index === 0 ? totalStars % starsContainers.length : 0);
    
    for (let i = 0; i < starsCount; i++) {
      const star = document.createElement('div');
      
      const x = Math.random() * 100;
      const y = Math.random() * 100;
      const size = Math.random() * (index + 1) + 1;
      const opacity = Math.random() * 0.8 + 0.2;
      
      star.style.cssText = `
        position: absolute;
        left: ${x}%;
        top: ${y}%;
        width: ${size}px;
        height: ${size}px;
        background: white;
        border-radius: 50%;
        opacity: ${opacity};
        box-shadow: 0 0 ${size * 2}px white;
        animation: twinkle ${Math.random() * 5 + 2}s infinite alternate;
      `;
      
      container.appendChild(star);
    }
  });
}

export default {
  components: {
    Navbar,
  },
  setup() {
    let redirectTimer = null;
    const targetUrl = 'https://123.56.203.202:8082/';
    const lastRedirectKey = 'lastRedirectTime';
    const twentyFourHours = 24 * 60 * 60 * 1000; // 24小时的毫秒数
    
    // 检查是否需要立即跳转
    const checkRedirect = () => {
      const lastTime = localStorage.getItem(lastRedirectKey);
      const now = Date.now();
      
      // 如果从未跳转过，或者已经超过24小时，则立即跳转
      if (!lastTime || (now - parseInt(lastTime) >= twentyFourHours)) {
        redirectToTarget();
        return true;
      }
      return false;
    };
    
    // 执行跳转
    const redirectToTarget = () => {
      console.log(`跳转到目标地址: ${targetUrl}`);
      window.location.href = targetUrl;
      localStorage.setItem(lastRedirectKey, Date.now().toString());
    };
    
    // 设置24小时后自动跳转的定时器
    const setupRedirectTimer = () => {
      // 清除可能存在的旧定时器
      if (redirectTimer) {
        clearInterval(redirectTimer);
      }
      
      // 计算距离下次跳转的时间（剩余时间）
      const lastTime = localStorage.getItem(lastRedirectKey);
      const now = Date.now();
      let timeToNextRedirect = twentyFourHours;
      
      if (lastTime) {
        const elapsed = now - parseInt(lastTime);
        timeToNextRedirect = Math.max(0, twentyFourHours - elapsed);
      }
      
      // 设置定时器，到达时间后跳转
      redirectTimer = setInterval(() => {
        redirectToTarget();
      }, timeToNextRedirect);
      
      console.log(`将在 ${timeToNextRedirect / (60 * 60 * 1000)} 小时后自动跳转`);
    };
    
    onMounted(() => {
      // 如果需要保留星空效果，取消下面一行的注释
      // createStars();
      
      // 检查是否需要立即跳转
      const justRedirected = checkRedirect();
      
      // 如果没有立即跳转，则设置定时器
      if (!justRedirected) {
        setupRedirectTimer();
      }
    });
    
    // 组件卸载时清除定时器
    onUnmounted(() => {
      if (redirectTimer) {
        clearInterval(redirectTimer);
      }
    });
  }
};
</script>

<style>
/* 主容器样式 */
.box-xk {
  width: 100%;
  min-height: 100vh;
  overflow: hidden;
  position: relative;
}

/* 黄瓜背景图片样式 */
.background-image {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: url('~@/../public/image.png'); /* 使用public目录下的image.png */
  background-size: cover; /* 覆盖整个容器 */
  background-position: center; /* 居中显示 */
  background-repeat: no-repeat; /* 不重复 */
  opacity: 1; /* 半透明效果，避免影响前景内容 */
  z-index: 0; /* 确保在内容下方 */
}

/* 如果保留星空效果，保留以下样式 */
#stars, #stars2, #stars3 {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none; /* 确保不影响鼠标交互 */
  z-index: 2; /* 星星在背景图片上方 */
}

/* 星星闪烁动画 */
@keyframes twinkle {
  0% {
    opacity: 0.3;
    transform: scale(1);
  }
  100% {
    opacity: 1;
    transform: scale(1.2);
  }
}

/* 星星移动动画 */
@keyframes moveStars {
  from {
    transform: translateY(0) translateX(0);
  }
  to {
    transform: translateY(-1000px) translateX(1000px);
  }
}

#stars {
  animation: moveStars 50s linear infinite;
}

#stars2 {
  animation: moveStars 80s linear infinite;
}

#stars3 {
  animation: moveStars 120s linear infinite;
}

/* 确保内容显示在背景上方 */
#app > div > Navbar,
#app > div > router-view {
  position: relative;
  z-index: 10; /* 内容在最上层 */
}
</style>
